import { Link } from 'react-router-dom';
import { useState, useEffect } from 'react';
import { Menu, X } from 'lucide-react';
import { motion, AnimatePresence } from 'motion/react';

export default function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 40);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  const navItems = [
    { href: '#about', label: 'About' },
    { href: '#work', label: 'Work' },
    { href: '#contact', label: 'Contact' },
  ];

  return (
    <motion.header
      initial={{ opacity: 0, y: -16 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, ease: 'easeOut' }}
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        scrolled
          ? 'bg-background/95 backdrop-blur-md border-b border-border'
          : 'bg-transparent'
      }`}
    >
      <div className="max-w-7xl mx-auto px-6 md:px-12">
        <div className="flex h-20 items-center justify-between">
          {/* Logo */}
          <Link to="/" className="flex items-center shrink-0" aria-label="Home">
            <img
              src="/airo-assets/images/logo/horizontal"
              alt="Portfolio logo"
              className="h-8 w-auto object-contain shrink-0"
            />
          </Link>

          {/* Desktop Nav */}
          <nav className="hidden md:flex items-center gap-10">
            {navItems.map((item) => (
              <a
                key={item.href}
                href={item.href}
                className="relative text-sm tracking-widest uppercase text-muted-foreground hover:text-foreground transition-colors duration-200 group"
              >
                {item.label}
                <span className="absolute -bottom-0.5 left-0 w-0 h-px bg-primary transition-all duration-200 group-hover:w-full" />
              </a>
            ))}
          </nav>

          {/* Mobile toggle */}
          <button
            onClick={() => setMobileOpen(!mobileOpen)}
            className="md:hidden p-2 text-muted-foreground hover:text-foreground transition-colors"
            aria-label="Toggle menu"
          >
            {mobileOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </div>
      </div>

      {/* Mobile menu */}
      <AnimatePresence>
        {mobileOpen && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.2, ease: 'easeOut' }}
            className="md:hidden bg-background/98 backdrop-blur-md border-b border-border overflow-hidden"
          >
            <nav className="flex flex-col px-6 py-6 gap-6">
              {navItems.map((item) => (
                <a
                  key={item.href}
                  href={item.href}
                  onClick={() => setMobileOpen(false)}
                  className="text-sm tracking-widest uppercase text-muted-foreground hover:text-foreground transition-colors"
                >
                  {item.label}
                </a>
              ))}
            </nav>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.header>
  );
}

export default function Footer() {
  const currentYear = new Date().getFullYear();

  const scrollToTop = (e: React.MouseEvent) => {
    e.preventDefault();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <footer className="border-t border-border bg-background">
      <div className="max-w-7xl mx-auto px-6 md:px-12 py-8">
        <div className="flex items-center justify-between">
          <p className="text-xs tracking-widest uppercase text-muted-foreground">
            © {currentYear} — All rights reserved
          </p>
          <a
            href="#top"
            onClick={scrollToTop}
            className="relative text-xs tracking-widest uppercase text-muted-foreground hover:text-primary transition-colors duration-200 group"
          >
            Back to top
            <span className="absolute -bottom-0.5 left-0 w-0 h-px bg-primary transition-all duration-200 group-hover:w-full" />
          </a>
        </div>
      </div>
    </footer>
  );
}

import { Helmet } from '@dr.pogodin/react-helmet';
import { motion } from 'motion/react';
import { Github, Linkedin, Twitter, ArrowDown, Mail } from 'lucide-react';

// ─── Animation Variants ───────────────────────────────────────────────────────

const fadeUp = {
  hidden: { opacity: 0, y: 24 },
  visible: (delay = 0) => ({
    opacity: 1,
    y: 0,
    transition: { duration: 0.5, ease: 'easeOut' as const, delay },
  }),
};

const fadeIn = {
  hidden: { opacity: 0, y: 16 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.6, ease: 'easeOut' as const },
  },
};

// ─── Social Link ──────────────────────────────────────────────────────────────

function SocialLink({
  href,
  label,
  children,
}: {
  href: string;
  label: string;
  children: React.ReactNode;
}) {
  return (
    <a
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      aria-label={label}
      className="flex items-center justify-center w-11 h-11 rounded-full border border-border text-muted-foreground hover:text-primary hover:border-primary transition-all duration-150 hover:scale-110"
    >
      {children}
    </a>
  );
}

// ─── Page ─────────────────────────────────────────────────────────────────────

export default function HomePage() {
  return (
    <>
      <Helmet>
        <title>Alex Morgan — Designer & Developer</title>
        <meta
          name="description"
          content="Personal portfolio of Alex Morgan — a designer and developer crafting thoughtful digital experiences."
        />
      </Helmet>

      {/* ── Hero ────────────────────────────────────────────────────────────── */}
      <section
        id="top"
        className="relative min-h-screen flex flex-col justify-center overflow-hidden"
      >
        {/* Subtle background texture */}
        <div className="absolute inset-0 pointer-events-none">
          <div
            className="absolute top-0 right-0 w-1/2 h-full opacity-[0.03]"
            style={{
              backgroundImage:
                'repeating-linear-gradient(0deg, hsl(var(--primary)) 0px, hsl(var(--primary)) 1px, transparent 1px, transparent 80px)',
            }}
          />
        </div>

        <div className="max-w-7xl mx-auto px-6 md:px-12 pt-32 pb-24 w-full">
          {/* Eyebrow */}
          <motion.p
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0}
            className="text-xs tracking-[0.3em] uppercase text-primary mb-8 font-sans"
          >
            Designer &amp; Developer
          </motion.p>

          {/* Name — oversized, breaks the grid */}
          <motion.h1
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0.1}
            className="font-heading text-[clamp(3.5rem,10vw,7.5rem)] leading-[0.92] tracking-tight text-foreground mb-0"
            style={{ fontFamily: 'var(--font-heading)' }}
          >
            Alex
            <br />
            Morgan.
          </motion.h1>

          {/* Accent rule */}
          <motion.div
            initial={{ scaleX: 0, originX: 0 }}
            animate={{ scaleX: 1 }}
            transition={{ duration: 0.6, delay: 0.35, ease: 'easeOut' as const }}
            className="h-px bg-primary w-24 my-8"
          />

          {/* Tagline */}
          <motion.p
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0.4}
            className="text-lg md:text-xl text-muted-foreground max-w-md leading-relaxed font-sans"
          >
            Crafting digital experiences that are as thoughtful as they are beautiful.
          </motion.p>

          {/* CTA links */}
          <motion.div
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0.55}
            className="flex items-center gap-8 mt-12"
          >
            <a
              href="#work"
              className="relative text-sm tracking-widest uppercase text-foreground hover:text-primary transition-colors duration-200 group"
            >
              View Work
              <span className="absolute -bottom-0.5 left-0 w-full h-px bg-primary scale-x-100 origin-left transition-transform duration-200" />
            </a>
            <a
              href="#contact"
              className="relative text-sm tracking-widest uppercase text-muted-foreground hover:text-foreground transition-colors duration-200 group"
            >
              Get in Touch
              <span className="absolute -bottom-0.5 left-0 w-0 h-px bg-primary transition-all duration-200 group-hover:w-full" />
            </a>
          </motion.div>
        </div>

        {/* Scroll indicator */}
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 1, duration: 0.6 }}
          className="absolute bottom-10 left-1/2 -translate-x-1/2 flex flex-col items-center gap-2 text-muted-foreground"
        >
          <span className="text-xs tracking-widest uppercase">Scroll</span>
          <motion.div
            animate={{ y: [0, 6, 0] }}
            transition={{ duration: 1.8, repeat: Infinity, ease: 'easeInOut' as const }}
          >
            <ArrowDown size={14} className="text-primary" />
          </motion.div>
        </motion.div>
      </section>

      {/* ── About ───────────────────────────────────────────────────────────── */}
      <section id="about" className="py-32 border-t border-border">
        <div className="max-w-7xl mx-auto px-6 md:px-12">
          {/* Section label */}
          <motion.p
            variants={fadeIn}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            className="text-xs tracking-[0.3em] uppercase text-primary mb-16 font-sans"
          >
            About
          </motion.p>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-16 md:gap-24 items-start">
            {/* Left — text */}
            <motion.div
              variants={fadeIn}
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true }}
              className="space-y-6"
            >
              <h2
                className="font-heading text-4xl md:text-5xl leading-tight text-foreground"
                style={{ fontFamily: 'var(--font-heading)' }}
              >
                Building with intention, designing with care.
              </h2>

              <div className="h-px bg-border w-full" />

              <p className="text-muted-foreground leading-relaxed font-sans">
                I'm a multidisciplinary designer and developer based in San Francisco. With over
                eight years of experience, I bridge the gap between design and engineering — turning
                complex problems into elegant, user-centered solutions.
              </p>
              <p className="text-muted-foreground leading-relaxed font-sans">
                My work spans product design, brand identity, and full-stack development. I believe
                the best digital experiences are born from a deep understanding of both craft and
                context.
              </p>

              {/* Skills */}
              <div className="pt-4">
                <p className="text-xs tracking-widest uppercase text-primary mb-4 font-sans">
                  Disciplines
                </p>
                <div className="flex flex-wrap gap-3">
                  {[
                    'Product Design',
                    'UI / UX',
                    'React',
                    'TypeScript',
                    'Brand Identity',
                    'Motion',
                  ].map((skill) => (
                    <span
                      key={skill}
                      className="text-xs tracking-wider uppercase px-3 py-1.5 border border-border text-muted-foreground font-sans"
                    >
                      {skill}
                    </span>
                  ))}
                </div>
              </div>
            </motion.div>

            {/* Right — decorative large initial */}
            <motion.div
              initial={{ opacity: 0, x: 24 }}
              whileInView={{ opacity: 1, x: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.7, ease: 'easeOut' as const, delay: 0.15 }}
              className="flex items-center justify-center md:justify-end"
            >
              <div className="relative select-none">
                {/* Large decorative letter */}
                <span
                  className="font-heading text-[clamp(12rem,22vw,18rem)] leading-none text-primary/10 tracking-tighter"
                  style={{ fontFamily: 'var(--font-heading)' }}
                  aria-hidden="true"
                >
                  A
                </span>
                {/* Geometric accent lines */}
                <div className="absolute top-1/2 -translate-y-1/2 right-0 flex flex-col gap-3">
                  <div className="w-16 h-px bg-primary/40" />
                  <div className="w-10 h-px bg-primary/25" />
                  <div className="w-6 h-px bg-primary/15" />
                </div>
                <div className="absolute bottom-8 left-8 w-px h-16 bg-primary/30" />
              </div>
            </motion.div>
          </div>
        </div>
      </section>

      {/* ── Work (placeholder) ──────────────────────────────────────────────── */}
      <section id="work" className="py-32 border-t border-border">
        <div className="max-w-7xl mx-auto px-6 md:px-12">
          <motion.p
            variants={fadeIn}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            className="text-xs tracking-[0.3em] uppercase text-primary mb-16 font-sans"
          >
            Selected Work
          </motion.p>

          <motion.div
            variants={fadeIn}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            className="grid grid-cols-1 md:grid-cols-2 gap-px bg-border"
          >
            {[
              { num: '01', title: 'Brand Identity System', tags: ['Branding', 'Strategy'] },
              { num: '02', title: 'Product Design Platform', tags: ['UI/UX', 'React'] },
              { num: '03', title: 'Editorial Web Experience', tags: ['Design', 'Motion'] },
              { num: '04', title: 'Mobile App Redesign', tags: ['iOS', 'UX Research'] },
            ].map((project) => (
              <div
                key={project.num}
                className="group bg-background p-10 cursor-pointer hover:bg-muted transition-colors duration-200"
              >
                <div className="flex items-start justify-between mb-8">
                  <span className="text-xs tracking-widest text-muted-foreground font-sans">
                    {project.num}
                  </span>
                  <div className="flex gap-2">
                    {project.tags.map((tag) => (
                      <span
                        key={tag}
                        className="text-xs tracking-wider uppercase px-2 py-1 border border-border text-muted-foreground font-sans"
                      >
                        {tag}
                      </span>
                    ))}
                  </div>
                </div>
                <h3
                  className="font-heading text-2xl md:text-3xl text-foreground group-hover:text-primary transition-colors duration-200"
                  style={{ fontFamily: 'var(--font-heading)' }}
                >
                  {project.title}
                </h3>
                <div className="mt-6 h-px w-0 bg-primary group-hover:w-12 transition-all duration-300" />
              </div>
            ))}
          </motion.div>
        </div>
      </section>

      {/* ── Contact ─────────────────────────────────────────────────────────── */}
      <section id="contact" className="py-32 border-t border-border">
        <div className="max-w-7xl mx-auto px-6 md:px-12">
          <motion.p
            variants={fadeIn}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            className="text-xs tracking-[0.3em] uppercase text-primary mb-16 font-sans"
          >
            Contact
          </motion.p>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-16 items-end">
            {/* Left — heading + email */}
            <motion.div
              variants={fadeIn}
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true }}
              className="space-y-10"
            >
              <h2
                className="font-heading text-4xl md:text-5xl leading-tight text-foreground"
                style={{ fontFamily: 'var(--font-heading)' }}
              >
                Let's make something worth remembering.
              </h2>

              <div>
                <p className="text-xs tracking-widest uppercase text-muted-foreground mb-4 font-sans">
                  Email
                </p>
                <a
                  href="mailto:hello@alexmorgan.design"
                  className="relative inline-flex items-center gap-3 text-xl md:text-2xl text-foreground hover:text-primary transition-colors duration-200 group font-sans"
                >
                  <Mail size={20} className="text-primary shrink-0" />
                  hello@alexmorgan.design
                  <span className="absolute -bottom-1 left-0 w-0 h-px bg-primary transition-all duration-200 group-hover:w-full" />
                </a>
              </div>
            </motion.div>

            {/* Right — social icons + availability */}
            <motion.div
              initial={{ opacity: 0, y: 16 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.6, ease: 'easeOut' as const, delay: 0.2 }}
              className="space-y-10 md:text-right"
            >
              <div>
                <p className="text-xs tracking-widest uppercase text-muted-foreground mb-6 font-sans">
                  Find me online
                </p>
                <div className="flex gap-3 md:justify-end">
                  <SocialLink href="https://github.com" label="GitHub">
                    <Github size={16} />
                  </SocialLink>
                  <SocialLink href="https://linkedin.com" label="LinkedIn">
                    <Linkedin size={16} />
                  </SocialLink>
                  <SocialLink href="https://twitter.com" label="Twitter / X">
                    <Twitter size={16} />
                  </SocialLink>
                </div>
              </div>

              <div className="inline-flex items-center gap-3 md:justify-end">
                <span className="w-2 h-2 rounded-full bg-primary animate-pulse" />
                <p className="text-sm text-muted-foreground font-sans">
                  Available for new projects
                </p>
              </div>
            </motion.div>
          </div>
        </div>
      </section>
    </>
  );
}
